import os
import json
from collections import Counter

def task_func(json_files_path='./json_files/', key='name'):
    counts = Counter()

    for filename in os.listdir(json_files_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_files_path, filename)
            with open(file_path, 'r') as file:
                data = json.load(file)
                if key in data:
                    value = data[key]
                    counts[value] += 1

    return dict(counts)

import os
import shutil

def task_func(src_dir, dest_dir, extension):
    if not os.path.exists(src_dir):
        print("Source directory does not exist.")
        return 0

    if not os.path.exists(dest_dir):
        os.makedirs(dest_dir)

    files_moved = 0
    for root, dirs, files in os.walk(src_dir):
        for file in files:
            if file.endswith(extension):
                file_path = os.path.join(root, file)
                dest_path = os.path.join(dest_dir, file)
                shutil.move(file_path, dest_path)
                files_moved += 1

    return files_moved

import heapq
import random

def task_func(obj_list, attr, top_n=5, seed=None):
    if seed is not None:
        random.seed(seed)

    if not obj_list or not hasattr(obj_list[0], attr):
        return [], None

    attr_values = [getattr(obj, attr) for obj in obj_list]
    top_n_values = heapq.nlargest(top_n, attr_values)

    if not attr_values:
        return [], None

    random_value = random.choice(attr_values)

    return top_n_values, random_value
